<?php
require_once 'app_bootstrap.php';require_once 'security.php';require_once 'booking-workflow.php';require_once 'notifications.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in.');if($_SERVER['REQUEST_METHOD']!=='POST')redirect_with_message('my-bookings.php','Use the booking request form.');verify_csrf();
$id=filter_input(INPUT_POST,'booking_id',FILTER_VALIDATE_INT)?:0;$type=$_POST['request_type']??'';$reason=trim($_POST['reason']??'');if(strlen($reason)<5||strlen($reason)>1000)redirect_with_message('my-bookings.php','Provide a clear reason for your request.');
try{$db=db_connect();ensure_app_schema($db);$db->begin_transaction();$booking=$db->execute_query('SELECT b.*,p.duration_days FROM bookings b LEFT JOIN packages p ON p.id=b.package_id WHERE b.id=? AND b.user_email=? FOR UPDATE',[$id,$_SESSION['user_email']])->fetch_assoc();if(!$booking)throw new RuntimeException('Booking not found.');$reference=$booking['booking_reference']?:'#'.$id;
if($type==='amend'){$active=active_booking_request($db,'booking_amendments',$id);if($active)throw new RuntimeException('An active date-change request already exists.');if(!in_array($booking['status'],['confirmed','in_progress'],true)||$booking['payment_status']!=='paid')throw new RuntimeException('Date-change requests are available only for paid active bookings.');$from=trim($_POST['requested_from_date']??'');$to=trim($_POST['requested_to_date']??'');$start=DateTimeImmutable::createFromFormat('!Y-m-d',$from);$end=DateTimeImmutable::createFromFormat('!Y-m-d',$to);$duration=max(1,(int)$booking['duration_days']);if(!$start||!$end||$start<new DateTimeImmutable('today')||$end->format('Y-m-d')!==$start->modify('+'.($duration-1).' days')->format('Y-m-d'))throw new RuntimeException('Choose a valid date range for this package.');$travellers=$db->execute_query('SELECT name,date_of_birth,family_member_id,traveller_type FROM booking_travellers WHERE booking_id=?',[$id])->fetch_all(MYSQLI_ASSOC);$includeSelf=false;$family=[];$others=[];foreach($travellers as $traveller){if($traveller['traveller_type']==='primary')$includeSelf=true;elseif($traveller['traveller_type']==='family')$family[]=(int)$traveller['family_member_id'];else$others[]=['name'=>$traveller['name'],'date_of_birth'=>$traveller['date_of_birth']];}$conflicts=booking_overlap_conflicts($db,$_SESSION['user_email'],$from,$to,$includeSelf,$family,$others,$id);if(array_filter($conflicts,fn($c)=>$c['severity']==='hard'))throw new RuntimeException('The requested dates overlap another confirmed trip.');$db->execute_query('INSERT INTO booking_amendments(booking_id,old_from_date,old_to_date,requested_from_date,requested_to_date,customer_reason) VALUES(?,?,?,?,?,?)',[$id,$booking['from_date'],$booking['to_date'],$from,$to,$reason]);$title='Date-change request received';$message='Your date-change request for booking '.$reference.' is awaiting review.';$adminTitle='Date-change request';}
elseif($type==='cancel'){$active=active_booking_request($db,'cancellation_requests',$id);if($active)throw new RuntimeException('An active cancellation request already exists.');if(!in_array($booking['status'],['confirmed','in_progress'],true)||$booking['payment_status']!=='paid'||empty($_POST['accept_policy']))throw new RuntimeException('Unpaid bookings can be deleted directly. Paid active bookings must use cancellation and refund request.');$quote=cancellation_quote($db,$booking);$db->execute_query('INSERT INTO cancellation_requests(booking_id,reason,paid_amount,policy_id,policy_name,refund_percentage,administrative_fee,estimated_refund) VALUES(?,?,?,?,?,?,?,?)',[$id,$reason,$quote['paid'],$quote['id'],$quote['name'],$quote['percentage'],$quote['fee'],$quote['refund']]);$title='Cancellation request received';$message='Your cancellation request for booking '.$reference.' is awaiting review. Estimated refund: '.inr($quote['refund']).'.';$adminTitle='Cancellation request';}else throw new RuntimeException('Invalid request type.');
$db->execute_query('INSERT INTO booking_status_history(booking_id,old_status,new_status,note,changed_by) VALUES(?,?,?,?,?)',[$id,$booking['status'],$booking['status'],$title.': '.$reason,'customer:'.$_SESSION['user_email']]);create_notification($db,$title,$message,'user',$_SESSION['user_email'],'my-bookings.php#booking-'.$id,'info');create_notification($db,$adminTitle,'Booking '.$reference.' requires administrator review.','admin',null,'admin/booking-details.php?id='.$id,'warning');$db->commit();redirect_with_message('my-bookings.php#booking-'.$id,$title.'.');
}catch(Throwable $error){if(isset($db)){try{$db->rollback();}catch(Throwable $ignored){}}redirect_with_message('my-bookings.php',$error->getMessage());}
